import { readFileSync, writeFileSync } from 'node:fs'
import { compileSchema } from './compiler.ts'

const source = 'reference/skland-wiki-v1.xsd'
const path = new URL('../../' + source, import.meta.url)
const output = new URL('../../packages/language-service/src/schema.generated.ts', import.meta.url)
const model = compileSchema(readFileSync(path, 'utf8'), source)
const generated =
  '// Generated by pnpm generate:schema.\nimport type { SchemaModel } from "./schema-model.js"\n\nexport const schema: SchemaModel = ' +
  JSON.stringify(model, null, 2) +
  '\n'

if (process.argv.includes('--check')) {
  if (readFileSync(output, 'utf8') !== generated)
    throw new Error('Schema metadata is stale. Run pnpm generate:schema.')
} else {
  writeFileSync(output, generated)
}
